/**
 * Builds the self-contained renderer helper block.
 *
 * The block is pure display logic: it rebuilds the provider-grouped catalog
 * into configured display groups, keeps `__provider` on every row so the
 * original route id is still submitted, and auto-collects unlisted free
 * models so channel syncs never make them vanish again.
 */

export const MARK_START = '/* DSH_PICKER_PATCH_START */';
export const MARK_END = '/* DSH_PICKER_PATCH_END */';

const HEAD = `/* DSH_PICKER_PATCH_START */
/* Grouped model picker — generated by dsh-model-picker-plugin. Edit config.json, then apply. */
const DSH_PICKER_CONFIG = `;

const TAIL = `;
const DSH_PICKER_TONE = {
  green: 'var(--dsw-alias-state-success-primary, #16a34a)',
  blue: 'var(--dsw-alias-state-business-primary, #2563eb)',
  amber: 'var(--dsw-alias-state-warn-label, #b45309)',
  gray: 'var(--dsw-alias-label-tertiary, #64748b)'
};
function dshPickerChipStyle(tone) {
  const color = DSH_PICKER_TONE[tone] || DSH_PICKER_TONE.gray;
  return { flex: 'none', fontSize: '11px', lineHeight: '16px', padding: '0 5px', borderRadius: '4px', border: '1px solid ' + color, color: color, background: 'transparent', whiteSpace: 'nowrap', maxWidth: '170px', overflow: 'hidden', textOverflow: 'ellipsis' };
}
function dshPickerMetaStyle() {
  return { display: 'block', fontSize: '11px', lineHeight: '15px', color: 'var(--dsw-alias-label-tertiary, #64748b)', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis', maxWidth: '100%' };
}
function dshPickerMeta(entry) {
  const parts = [];
  if (entry.quality) parts.push('质量 ' + entry.quality);
  if (entry.speed) parts.push('速度 ' + entry.speed);
  if (entry.tags && entry.tags.length) parts.push(entry.tags.join(' / '));
  return parts.join('  ·  ');
}
function dshPickerTitle(entry, providerId, model) {
  const id = providerId + '/' + model.id;
  return entry ? id + '  ·  ' + dshPickerMeta(entry) : id;
}
function dshPickerProvider(group, model) {
  return model && model.__provider ? Object.assign({}, group.provider, { id: model.__provider }) : group.provider;
}
function dshPickerAutoEntry(model, providerId, isFree, isBad, isVision) {
  const auto = DSH_PICKER_CONFIG.autoGroups || {};
  const name = String(model.name || '');
  let badge, tone;
  if (isBad) {
    badge = name.includes('地区受限') ? '🌏 地区受限' : name.includes('未实测') ? '⚠️ 未实测' : '⚠️ 额度用尽';
    tone = 'amber';
  } else if (isFree) {
    badge = name.includes('🟢') ? '🟢 免费·极速'
      : name.includes('🔵') ? '🔵 免费·稳定'
      : name.includes('🟡') ? '🟡 免费·偏慢'
      : (auto.free && auto.free.badge) || '免费·可用';
    tone = name.includes('🟡') ? 'amber' : name.includes('🔵') ? 'blue' : 'green';
  } else {
    badge = (auto.other && auto.other.badge) || '其他';
    tone = 'gray';
  }
  const tags = [providerId];
  if (isVision) tags.push('◉识图版');
  if (isFree && !isBad) tags.push('免费');
  return { badge: badge, tone: tone, quality: '', speed: '', tags: tags };
}
/** Auto-collect unpinned models so free channels never disappear after a catalog sync. */
function dshPickerAutoGroups(groups, listed) {
  const auto = DSH_PICKER_CONFIG.autoGroups || {};
  if (DSH_PICKER_CONFIG.hideUnlisted === true || auto.enabled === false) return [];
  const freeDef = auto.free || {}, otherDef = auto.other || {};
  const dedupe = auto.dedupeVision !== false;
  const plain = new Set();
  if (dedupe) {
    for (const g of groups || []) {
      if (/-vision$/.test(g.id)) continue;
      for (const m of g.models || []) plain.add(m.id + '|' + String(m.name || ''));
    }
  }
  const freeHints = auto.freeNameHints || ['免费'];
  const badHints = auto.badNameHints || [];
  const free = [], other = [];
  for (const g of groups || []) for (const m of g.models || []) {
    const full = g.id + '/' + m.id;
    if (listed.has(full) || listed.has(m.id)) continue;
    const isVision = /-vision$/.test(g.id);
    if (isVision && dedupe && plain.has(m.id + '|' + String(m.name || ''))) continue;
    const name = String(m.name || '');
    const isFree = freeHints.some(h => name.includes(h));
    const isBad = badHints.some(h => name.includes(h));
    const row = Object.assign({}, m, {
      __provider: g.id,
      __dsh: dshPickerAutoEntry(m, g.id, isFree, isBad, isVision)
    });
    if (isFree && !isBad && freeDef.enabled !== false) free.push(row);
    else if (otherDef.enabled !== false) other.push(row);
  }
  const out = [];
  if (free.length) {
    const label = freeDef.label || '3  其他免费可用';
    out.push({ id: 'dsh-picker-free', name: label, provider: { id: 'dsh-picker-free', name: label }, models: free });
  }
  if (other.length) {
    const label = otherDef.label || '4  其余模型';
    out.push({ id: 'dsh-picker-other', name: label, provider: { id: 'dsh-picker-other', name: label }, models: other });
  }
  return out;
}
/** Rebuild display groups; every row keeps its real route id in __provider. */
function dshPickerGroups(groups) {
  const found = new Map();
  for (const group of groups || []) {
    for (const model of group.models || []) {
      const full = group.id + '/' + model.id;
      const entry = DSH_PICKER_CONFIG.models.find(m => m.id === full || m.id === model.id);
      if (!entry) continue;
      const hit = { entry, providerId: group.id, model };
      found.set(model.id, hit);
      found.set(full, hit);
    }
  }
  const out = [];
  for (const def of DSH_PICKER_CONFIG.groups) {
    const models = [];
    for (const entry of DSH_PICKER_CONFIG.models) {
      if (entry.group !== def.id) continue;
      const hit = found.get(entry.id);
      if (!hit) continue;
      models.push(Object.assign({}, hit.model, {
        __provider: hit.providerId,
        __dsh: entry,
        name: entry.name || hit.model.name
      }));
    }
    if (models.length === 0) continue;
    const gid = 'dsh-picker-' + def.id;
    out.push({ id: gid, name: def.label, provider: { id: gid, name: def.label }, models });
  }
  const listed = new Set(DSH_PICKER_CONFIG.models.map(m => m.id));
  out.push(...dshPickerAutoGroups(groups, listed));
  return out;
}
/* DSH_PICKER_PATCH_END */
`;

/** Validate the shape of a user config before embedding it in JS. */
export function validateConfig(cfg) {
  if (!cfg || typeof cfg !== 'object') throw new Error('config must be an object');
  if (!Array.isArray(cfg.groups) || cfg.groups.length === 0) throw new Error('config.groups must be a non-empty array');
  if (!Array.isArray(cfg.models)) throw new Error('config.models must be an array');
  const gids = new Set(cfg.groups.map(g => g && g.id));
  const ids = new Set();
  for (const m of cfg.models) {
    if (!m || typeof m.id !== 'string' || !m.id) throw new Error('every model needs a non-empty id');
    if (ids.has(m.id)) throw new Error('duplicate model id: ' + m.id);
    ids.add(m.id);
    if (!gids.has(m.group)) throw new Error('unknown group for: ' + m.id);
  }
  return cfg;
}

export function buildHelper(cfg) {
  return HEAD + JSON.stringify(validateConfig(cfg), null, 2) + TAIL;
}

export function helperBlockOf(src) {
  const a = src.indexOf(MARK_START);
  const b = src.indexOf(MARK_END);
  if (a < 0 || b < 0 || b < a) return null;
  return { start: a, end: b + MARK_END.length, text: src.slice(a, b + MARK_END.length) };
}
